from save_review import save
import json,re
from pathlib import Path
D=Path(__file__).resolve().parents[2];corpus={a['number']:a for a in json.loads((D/'全书分段底稿.json').read_text())}
def finish(n,ed,notes=None,terms=None,title=None):
 bs={int(b['id'][-4:]):b for b in corpus[n]['blocks']}
 for i,b in bs.items():
  if b.get('language')!='en' or i+1 not in bs or bs[i+1].get('language')!='zh':continue
  s=ed.get(i+1,bs[i+1]['text'])
  for x,y in [('哈洗录深渊','哈冼录深渊'),('戈尔根纳河段','戈尔根纳疆域'),('乔西安河段','约西亚疆域'),('杰里科河段','杰里科疆域'),('阿德兰蒂斯','阿德兰提斯'),('鹰覆家族','覆隼家族'),('卡洛斯','卡罗斯'),('莫比安领域','莫比亚领地')]:s=s.replace(x,y)
  if 'Dead World' in b['text']:s=s.replace('死亡世界','死寂世界')
  if re.search(r'sub.?sector',b['text'],re.I):s=s.replace('分区','次星区')
  if s!=bs[i+1]['text']:ed[i+1]=s
 save(n,ed,notes=notes,terms=terms,title=title)
finish(871,{2:'封建世界，又称中世纪世界，在帝国行星分类中属于μ类，其科技水平相当于中世纪。最先进的封建世界拥有黑火药武器，不过，有些居民仍保有机械义体。由于农业有所发展，这类行星的什一税略高于蛮荒世界，通常介于 Solutio Prima 与 Solutio Extremis 之间，原稿暂译“第三级上等”至“第三级高等”。人口一般为1000万至5亿。',4:'Image of a Feudal World. Observe the bionics on the Imperial denizen 封建世界图景。注意这名帝国居民身上的机械义体。',6:'封建世界能够自给自足；由于依赖农业，大部分居民是农民，通常由尚武贵族统治。这类世界对帝国的用处相对有限。居民一旦得知故乡在浩瀚宇宙中的真实地位，可能遭受强烈的文化冲击，因而往往不易适应帝国服役生活。不过，尚武贵族仍是星际战士的重要兵源。',15:'巴拉特雷德——帝国；人口稀少。',19:'卡德里斯——极限星域；科里亚尼斯星区、奥瑞利亚次星区；人口2500万；帝国；也是沙漠世界。',25:'科拉拉克斯——位于帝国边界之外、极限星域以东；帝国；渡鸦骑士战团的母星。',29:'库斯托十一号（原封建世界）——原属帝国；现为死寂世界；曾是火鹰战团的母星。',44:'曼科拉——极限星域；帝国；咆哮狮鹫战团的母星，同时也是特雷纳家族的骑士世界。',48:'圣礼星——朦胧星域；卡利西斯星区、德鲁苏斯边区；帝国；风暴守望者战团的母星，也是禁忌世界。',50:'塞菲里斯二号——朦胧星域；卡利西斯星区、戈尔根纳疆域；人口120亿；帝国；也是矿业世界。',54:'西斯科——朦胧星域；卡利西斯星区、边陲；帝国。',56:'庄严星——庄严星系；帝国；底稿列为黑色圣堂昔日母星，也是禁忌世界。',62:'塔尼斯（原封建世界）——太平星域；安息日诸世界、塔尼斯星系；人口为零；现为死寂世界。',64:'宁静二号——极限星域；大漩涡区域；人口数千；帝国。'},notes={2:'10,000,000 为1000万，原译一亿多了一位。μ为分类代码，不是行政等级。',4:'Imperial denizen 是帝国居民，并非皇室成员。',6:'poor material 指不适宜征用服役，不是值得同情的“可怜材料”。',15:'Sparse 按清单语境解作人口稀少；原文没有保留列标题，待核。',56:'保留原文 Former Homeworld 的说法，不凭战团常见舰基传统删改此历史条目。'},terms=[('Feudal World','封建世界'),('Medieval World','中世纪世界'),('Korianis Sector','科里亚尼斯星区'),('Malfian Sub-Sector','马尔菲安次星区'),('The Periphery','边陲'),('Sabbat Worlds','安息日诸世界')])
bs={int(b['id'][-4:]):b for b in corpus[872]['blocks']};en=bs[1]['text'].split(' 随着帝国')[0]
finish(872,{1:en+' 帝国始终处于战争之中，因此将一些世界指定为堡垒世界，以抵御神皇之敌。你也是防线的一员，守住城门，不让外面的邪恶攻入。由此，你分享着帝国强大战争机器的荣耀。',3:'堡垒世界是帝国的一种行星类别，全体居民的生活都围绕战争展开。这些世界被建成堡垒，以抵御特定威胁。最著名的堡垒世界曾是卡迪亚，它扼守恐惧之眼入口处的卡迪亚之门。在帝国行政分类中，研究站与堡垒世界有所重叠，两者都属于ρ类。',5:'不屈远征发起后，许多堡垒世界正被改造成枢纽堡垒，以支援战争行动。',20:'卡迪亚——朦胧星域；卡迪亚星区、卡迪亚次星区、卡迪亚星系；原人口8.5亿；帝国；现已毁灭。',24:'凯尔森——极限星域；灾祸降临星系；帝国。',26:'科洛尼斯·阿加松——朦胧星域；人口1200亿；帝国。',30:'雅各——太平星域；安息日诸世界；帝国。',44:'莫隆德——太平星域；安息日诸世界；帝国。',52:'赤地星——朦胧星域；格兰达尔次星区、赤血星系；帝国；圣墙防线的关键支点，位于纳克蒙德走廊南端。',64:'瓦斯’塔罗斯（原名总督星）——极限星域；达摩克利斯湾、多瓦尔星系；原属帝国，后被钛帝国征服，现为钛世界。'},notes={1:'保留英文原段与第二人称叙述，中文改写机械直译。',20:'世界毁灭后的状态与毁灭前人口分开表述，未将8.5亿说成现有居民。',26:'原文确为120,000,000,000，即1200亿；未擅自因数字庞大而改成120亿。',52:'Lynch-pin 即 linchpin，意思是关键支点，不是专名“林奇楔”。'},terms=[('Fortress World','堡垒世界'),('Hub-Fortress','枢纽堡垒'),('Sanctus Wall','圣墙防线'),('Sangua Terra','赤地星'),('Gorandahl Sub-Sector','格兰达尔次星区'),('Bane\'s Landing System','灾祸降临星系'),('Vas\'talos','瓦斯’塔罗斯')])
finish(873,{2:'工业世界，又称制造世界，是整颗星球都投入制造或采矿的工厂世界。由于大部分劳动由机械完成，这些世界通常人口稀少。工业化采矿世界必须有足够丰富的矿藏，才能使庞大的运输与开发投入值得付出。工业世界虽然可能与机械修会有联系，却并不像铸造世界那样归机械修会所有。',17:'布兰克斯·马格纳——太阳星域；帝国；莫比亚领地中工业产量可观的世界。',29:'恩底弥翁一号——极限星域；帝国；人口11亿，包括人类与亚人。',33:'火风暴星——极限星域；帝国；曙光女神战团的母星。',51:'科洛万（原工业世界）——帝国；现为死寂世界，无人居住。',69:'凡廷——太平星域；帝国；安息日诸世界远征期间曾被混沌军队占领。',75:'拉沙德主星——帝国；也是战争世界和农业世界。',85:'塔尔尼斯——帝国；也是战争世界，曾为德拉库斯家族的骑士世界。',89:'沃斯特洛亚——朦胧星域；帝国；人口约93亿；以帝国卫队的沃斯特洛亚长子团闻名。'},notes={2:'修正悬空代词“他们”：不拥有工业世界的主体是机械修会，不是行星本身。矿产必须足以抵偿开发投入，并非为某项政策“证明合理性”。',7:'Belial 在此是工业世界彼列，不是暗黑天使人物贝利亚。',89:'依核心表统一母星与沃斯特洛亚长子团；未套用星际战士的长子类别。'},terms=[('Industrial World','工业世界'),('Manufactory World','制造世界'),('Branx Magna','布兰克斯·马格纳'),('House Drakkus','德拉库斯家族')])
finish(874,{4:'骑士世界诞生于黑暗科技时代人类蓬勃发展的时期。当时，人类刚开始从泰拉与太阳系向外扩张。不断壮大的人类需要更多原材料，因此前往这些世界定居：肥沃星球用于农业，富矿星球用于采掘。',6:'从泰拉出发的长征舰队中，有庞大的殖民舰，每艘都载着数千名定居者。舰船落地后会被拆解，用作建设最初聚落的材料。舰队还携带先进的骑士机甲及其驾驶员。这些骑士常常决定着殖民地是兴盛还是覆灭；驾驶员掌握的力量足够强大，因而成为所在世界事实上的统治者。',8:'纷争时代，亚空间风暴使这些世界与其他人类疆域隔绝。凭借尚武传统与保守的生活方式，它们往往较能躲过当时的战乱。在漫长的孤立中，骑士世界逐渐形成封建制度，由等级分明的贵族阶层掌握骑士机甲，并统治世界本身。',10:'大远征期间，军务行商浪人巴斯蒂安·杰弗斯在太阳星域重新发现克律西斯，骑士世界由此开始重新融入人类疆域、加入帝国。此后，泰拉高领主与机械修会都积极争取这些世界的力量和技术。后来重归人类统治的骑士世界，便分别效忠泰拉或火星。',12:'某些骑士世界——例如塔兰尼斯家族的领地——会献出部分居民作为贡赋，将他们改造成机械教的护教军督查。这些“原材料”往往拥有优良的遗传素质，被称为 Psychosis-Neuracanium，现稿暂译“灵能神经颅”。',31:'巴罗达——朦胧星域；马卡比乌斯家族；现归属不明，推测仍属混沌；荷鲁斯之乱期间曾宣誓效忠荷鲁斯。',43:'迎死星——帝国；有多个骑士家族。',61:'高岩星（原骑士世界）——维瑞迪昂家族；现归属不明，原属帝国；现为死寂世界。',85:'曼科拉——极限星域；特雷纳家族；帝国；咆哮狮鹫战团的母星，同时也是封建世界。',105:'狂喜星（原骑士世界）——暴风星域；阿拉莫斯家族；帝国；现为死寂世界，过去也是天堂世界。',115:'冥河星（原骑士世界）——帝国；底稿人口栏记为1；现为死寂世界。',119:'塔尔尼斯（原骑士世界）——德拉库斯家族；帝国；现为战争世界和工业世界。'},notes={10:'court 在此为争取支持；allegiance split 表示不同骑士世界各有归属，并非每颗世界都陷入分裂。Rogue Trader Militant 职衔暂译军务行商浪人，官方待核。',12:'submit a tribute of its citizens 是献出居民作贡赋，原“向公民致敬”颠倒含义。Psychosis-Neuracanium 的原稿译名缺乏直接官方依据，保留英文与待核标记。',39:'Damaetus III/II 的数字组合原文如此，未擅改为单一编号。',43:'Multiple 位于骑士家族这一语境，按多个家族处理；具体名称未给出。',77:'House Hawk shroud 为 Hawkshroud 的分词变体，依核心表统一覆隼家族。',115:'人口1与死寂世界状态并列，无法据此确认当前居民数量，保留原记录待核。'},terms=[('Knight World','骑士世界'),('Knight House','骑士家族'),('Rogue Trader Militant','军务行商浪人'),('Bastian Jeffers','巴斯蒂安·杰弗斯'),('Long March','长征'),('Psychosis-Neuracanium','灵能神经颅'),('Skitarii Overseer','护教军督查')])
finish(875,{2:'矿业世界，即Ю类世界，蕴藏着制造厂与铸造世界所需的丰富原材料。奴隶和囚犯劳工在这些星球开采资源，无论是气体、矿石，还是帝国需要的其他矿物。许多矿业世界的环境并不适合人类居住。',15:'巴巴鲁斯一号（原矿业世界）——极限星域；帝国；毁灭前人口9000；现为死寂世界。',17:'贝利斯——朦胧星域；帝国；其卫星上有丰富矿藏。曾试图脱离帝国，后被暗黑天使重新置于帝国统治之下。',19:'贝塔利斯三号——太阳星域；帝国；人口6200万；也是冰雪世界。',21:'卡加利安九号——朦胧星域；帝国／基因窃取者教派；已被锈爪教派控制。',25:'钦查尔——朦胧星域；帝国；仅保留维持运作所需的矿工和相关人员，约5000人。',29:'科索尼亚（原矿业世界）——太阳星域；归属不适用，已无人居住，现已毁灭；曾是荷鲁斯之子的母星。',35:'拯救星——暴风星域；帝国；暗鸦守卫的母星。',46:'杰维奥克斯——太阳星域；帝国；人口500万。',48:'戈萨尔五号——极限星域；帝国；人口1500万；遭基因窃取者教派渗透。帝国记录将其列为“深掘世界”（Delverworld），即因开采珍贵矿物而遍布掘痕的世界。',60:'伊什塔尔九号——帝国；入侵前人口2000万；161.M32年恶魔入侵时，全体居民遭到杀戮。',62:'伊克西亚（原矿业世界）——太平星域；太空死灵；也是古墓世界，现已无人类居民。',66:'木星——太阳星域；太阳系；帝国；也是铸造世界。',90:'莫纳克斯——太阳星域；帝国；莫比亚领地所属世界。',94:'纳克索斯——朦胧星域；帝国；矿工及相关人员共40万人。',105:'帕沃尼斯——极限星域；帝国；人口3亿。',117:'薛定谔七号（原矿业世界）——现属太空死灵，原属帝国；也是古墓世界和冰雪世界，过去曾是巢都世界。',119:'塞菲里斯二号——朦胧星域；帝国；人口120亿；也是封建世界。',133:'桑德罗斯星系诸行星——极限星域东部边缘；帝国；包括桑德罗斯二号与桑德罗斯三号两颗矿业世界。',147:'祖图斯——帝国；以带电云层著称。'},notes={2:'Ю为源文中的西里尔字母分类代码，予以保留。penal workers 是囚犯劳工，不是泛指受惩罚的人。',25:'skeleton crew 是维持运作的最少人员，并非骷髅船员。',48:'scored of precious minerals 语法疑似有误，按 Delverworld 采掘语境暂解为矿业开采留下掘痕；不是整颗星球由贵重矿物组成，保留英文供核。',62:'without humans 只说明无人类，不等于没有太空死灵或任何其他居民。',66:'Solar 为太阳星域，原译太平星域错误。',119:'补回原译遗漏的封建世界分类。'},terms=[('Mining World','矿业世界'),('Delverworld','深掘世界'),('Cult of the Rusted Claw','锈爪教派'),('Thandros System','桑德罗斯星系')])
